-- JANET Virtual Airlines Ecosystem: production foundation
create extension if not exists pgcrypto;
create type public.app_role as enum ('applicant','pilot','captain','instructor','dispatcher','maintenance_controller','fleet_manager','chief_pilot','operations_manager','owner','system_administrator');
create type public.flight_status as enum ('draft','generated','awaiting_dispatch','released','crew_assigned','briefing_ready','preflight','boarding','ready','off_block','airborne','landed','on_block','pirep_pending','completed','delayed','diverted','cancelled');
create type public.aircraft_status as enum ('available','assigned','boarding','airborne','maintenance','grounded','ferry_required','stored','retired');
create type public.pirep_status as enum ('pending','automatically_accepted','manual_review','accepted','rejected','returned_for_correction');

create table public.airports(id uuid primary key default gen_random_uuid(),icao text unique,iata text,local_code text,name text not null,city text,state text,country text not null default 'US',latitude double precision not null,longitude double precision not null,elevation_ft int,timezone text not null,airport_type text,real_world_reference_code text,simulator_airport_code text,preferred_navigation_code text,display_label text,active boolean default true,public_visibility boolean default false,notes text,created_at timestamptz default now());
create table public.profiles(id uuid primary key references auth.users on delete cascade,employee_number text unique,display_name text not null,legal_name_optional text,email text,avatar_path text,role public.app_role default 'applicant',rank text,status text default 'active',home_base_id uuid references public.airports,timezone text default 'UTC',simulator_preferences jsonb default '{}',vatsim_cid text,ivao_id text,hire_date date,last_active_at timestamptz,forced_password_reset boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.user_roles(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles on delete cascade,role public.app_role not null,granted_by uuid references public.profiles,granted_at timestamptz default now(),expires_at timestamptz,active boolean default true,unique(user_id,role));
create table public.applications(id uuid primary key default gen_random_uuid(),applicant_user_id uuid not null references public.profiles,status text default 'submitted',answers jsonb not null default '{}',reviewer_id uuid references public.profiles,reviewer_notes text,submitted_at timestamptz default now(),reviewed_at timestamptz);
create table public.availability_entries(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,start_at timestamptz,end_at timestamptz,availability_type text,notes text,recurrence_rule text,check(end_at>start_at));
create table public.stations(id uuid primary key default gen_random_uuid(),airport_id uuid not null references public.airports,station_code text unique not null,display_name text not null,operational_name text,restricted_label text,active boolean default true,sort_order int default 0);
create table public.aircraft_types(id uuid primary key default gen_random_uuid(),code text unique not null,name text not null,category text not null,manufacturer text,default_capacity int,active boolean default true);
create table public.routes(id uuid primary key default gen_random_uuid(),origin_airport_id uuid references public.airports,destination_airport_id uuid references public.airports,route_category text,default_aircraft_type_id uuid references public.aircraft_types,estimated_block_minutes int,outbound_altitude_ft int,return_altitude_ft int,frequency_weight numeric default 1,active_days int[] default '{1,2,3,4,5}',version int default 1,active boolean default true,public_visibility boolean default false,notes text,unique(origin_airport_id,destination_airport_id,version));
create table public.route_variants(id uuid primary key default gen_random_uuid(),route_id uuid references public.routes on delete cascade,route_string text,minimum_altitude int,maximum_altitude int,route_conditions text,simulator_notes text,active boolean default true);
create table public.aircraft(id uuid primary key default gen_random_uuid(),registration text unique not null,fleet_number text unique,aircraft_type_id uuid references public.aircraft_types,serial_number text,current_airport_id uuid references public.airports,status public.aircraft_status default 'available',total_hours numeric default 0,total_cycles int default 0,hours_since_service numeric default 0,cycles_since_service int default 0,fuel_quantity numeric,passenger_capacity int,cargo_capacity numeric,livery_path text,active boolean default true,maintenance_due_at timestamptz,maintenance_due_hours numeric,notes text,updated_at timestamptz default now());
create table public.aircraft_status_history(id bigint generated always as identity primary key,aircraft_id uuid references public.aircraft,status public.aircraft_status not null,airport_id uuid references public.airports,reason text,actor_id uuid references public.profiles,created_at timestamptz default now());
create table public.aircraft_defects(id uuid primary key default gen_random_uuid(),aircraft_id uuid references public.aircraft,title text not null,description text,severity text,status text default 'open',reported_by uuid references public.profiles,resolved_by uuid references public.profiles,created_at timestamptz default now(),resolved_at timestamptz);
create table public.maintenance_events(id uuid primary key default gen_random_uuid(),aircraft_id uuid references public.aircraft,event_type text,status text,scheduled_at timestamptz,completed_at timestamptz,notes text,created_by uuid references public.profiles);
create table public.schedule_templates(id uuid primary key default gen_random_uuid(),name text not null,callsign_template text not null,flight_number text,origin_airport_id uuid references public.airports,destination_airport_id uuid references public.airports,scheduled_departure_local time,scheduled_arrival_local time,days_of_week int[] default '{1,2,3,4,5}',aircraft_category text,preferred_aircraft_type_id uuid references public.aircraft_types,altitude_ft int,operation_type text,variability_minutes int default 0,operation_probability numeric default 1 check(operation_probability between 0 and 1),start_date date,end_date date,active boolean default true,source_reference text,admin_notes text,preset_name text,generation_reason text);
create table public.schedule_exceptions(id uuid primary key default gen_random_uuid(),schedule_template_id uuid references public.schedule_templates on delete cascade,date date,exception_type text,replacement_departure time,replacement_arrival time,reason text,unique(schedule_template_id,date));
create table public.missions(id uuid primary key default gen_random_uuid(),mission_number text unique,title text,category text,full_description text,redacted_description text,priority text,access_tier text,requesting_department text,origin text,destination text,required_arrival_window tstzrange,passenger_count int,cargo_weight numeric,handling_instructions text,status text,generated boolean default false,approved_by uuid references public.profiles,created_at timestamptz default now());
create table public.flights(id uuid primary key default gen_random_uuid(),flight_number text,spoken_callsign text,tracking_callsign text not null,mission_id uuid references public.missions,schedule_template_id uuid references public.schedule_templates,origin_airport_id uuid references public.airports,destination_airport_id uuid references public.airports,alternate_airport_id uuid references public.airports,aircraft_id uuid references public.aircraft,dispatcher_id uuid references public.profiles,captain_id uuid references public.profiles,first_officer_id uuid references public.profiles,scheduled_departure timestamptz not null,scheduled_arrival timestamptz not null,estimated_departure timestamptz,estimated_arrival timestamptz,actual_off_block timestamptz,actual_takeoff timestamptz,actual_landing timestamptz,actual_on_block timestamptz,planned_altitude_ft int,route_string text,status public.flight_status default 'draft',delay_code text,cancellation_reason text,passenger_count int default 0,cargo_weight numeric default 0,public_visibility boolean default false,generation_reason jsonb default '{}',created_at timestamptz default now(),updated_at timestamptz default now(),unique(schedule_template_id,scheduled_departure),check(scheduled_arrival>scheduled_departure));
create index flights_window_idx on public.flights(scheduled_departure,status); create index flights_aircraft_idx on public.flights(aircraft_id,scheduled_departure);
create table public.flight_status_events(id bigint generated always as identity primary key,flight_id uuid references public.flights on delete cascade,from_status public.flight_status,to_status public.flight_status not null,actor_id uuid references public.profiles,reason text,metadata jsonb default '{}',created_at timestamptz default now());
create table public.qualifications(id uuid primary key default gen_random_uuid(),code text unique,name text,aircraft_type_id uuid references public.aircraft_types,validity_days int,active boolean default true);
create table public.user_qualifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,qualification_id uuid references public.qualifications,issued_by uuid references public.profiles,issued_at timestamptz default now(),expires_at timestamptz,status text default 'active',unique(user_id,qualification_id));
create table public.crew_assignments(id uuid primary key default gen_random_uuid(),flight_id uuid references public.flights on delete cascade,user_id uuid references public.profiles,position text not null,status text default 'assigned',assigned_by uuid references public.profiles,assigned_at timestamptz default now(),unique(flight_id,position),unique(flight_id,user_id));
create table public.dispatch_releases(id uuid primary key default gen_random_uuid(),flight_id uuid references public.flights,release_number text unique,revision_number int default 1,aircraft_id uuid references public.aircraft,dispatcher_id uuid references public.profiles,route text,cruise_altitude int,estimated_block_minutes int,trip_fuel numeric,contingency_fuel numeric,alternate_fuel numeric,reserve_fuel numeric,taxi_fuel numeric,block_fuel numeric,passenger_count int,cargo_weight numeric,weather_summary text,alternate_airport_id uuid references public.airports,dispatcher_remarks text,operational_restrictions text,captain_accepted_by uuid references public.profiles,captain_accepted_at timestamptz,issued_at timestamptz default now());
create table public.dispatch_release_revisions(id bigint generated always as identity primary key,release_id uuid references public.dispatch_releases,revision_number int,snapshot jsonb not null,reason text,actor_id uuid references public.profiles,created_at timestamptz default now(),unique(release_id,revision_number));
create table public.acars_sessions(id uuid primary key default gen_random_uuid(),flight_id uuid references public.flights,pilot_id uuid references public.profiles,aircraft_id uuid references public.aircraft,simulator text,client_version text,status text default 'active',started_at timestamptz default now(),ended_at timestamptz);
create table public.flight_telemetry_points(id bigint generated always as identity,session_id uuid references public.acars_sessions on delete cascade,recorded_at timestamptz default now(),latitude double precision,longitude double precision,altitude int,heading int,ground_speed int,vertical_speed int,fuel numeric,on_ground boolean,payload jsonb,primary key(id,recorded_at));
create index telemetry_session_idx on public.flight_telemetry_points(session_id,recorded_at desc);
create table public.flight_events(id bigint generated always as identity primary key,session_id uuid references public.acars_sessions,event_type text,detected boolean default true,payload jsonb default '{}',occurred_at timestamptz default now());
create table public.pireps(id uuid primary key default gen_random_uuid(),flight_id uuid unique references public.flights,pilot_id uuid references public.profiles,aircraft_id uuid references public.aircraft,simulator text,addon text,block_minutes int,flight_minutes int,fuel_used numeric,landing_rate int,route_flown text,remarks text,detected_violations jsonb default '[]',score numeric,status public.pirep_status default 'pending',reviewer_id uuid references public.profiles,submitted_at timestamptz default now(),reviewed_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles,type text,title text,body text,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,previous_values jsonb,new_values jsonb,request_id uuid,ip_hash text,user_agent text,reason text,created_at timestamptz default now());

create or replace function public.has_role(p_user uuid,p_role public.app_role) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=p_user and role=p_role and active and (expires_at is null or expires_at>now()))$$;
create or replace function public.has_any_role(p_user uuid,p_roles public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=p_user and role=any(p_roles) and active and (expires_at is null or expires_at>now()))$$;
create or replace function public.is_flight_crew(p_user uuid,p_flight uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.crew_assignments where user_id=p_user and flight_id=p_flight)$$;
create or replace function public.can_access_flight(p_user uuid,p_flight uuid) returns boolean language sql stable security definer set search_path='' as $$select public.is_flight_crew(p_user,p_flight) or public.has_any_role(p_user,array['dispatcher','chief_pilot','operations_manager','owner','system_administrator']::public.app_role[])$$;

create or replace function public.capture_flight_status() returns trigger language plpgsql security definer set search_path='' as $$begin if old.status is distinct from new.status then insert into public.flight_status_events(flight_id,from_status,to_status,actor_id) values(new.id,old.status,new.status,auth.uid()); end if; new.updated_at=now(); return new; end$$;
create trigger flight_status_audit before update on public.flights for each row execute function public.capture_flight_status();
create or replace function public.protect_audit_log() returns trigger language plpgsql as $$begin raise exception 'audit_logs are append-only'; end$$;
create trigger audit_immutable before update or delete on public.audit_logs for each row execute function public.protect_audit_log();

alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.applications enable row level security; alter table public.availability_entries enable row level security; alter table public.airports enable row level security; alter table public.stations enable row level security; alter table public.routes enable row level security; alter table public.route_variants enable row level security; alter table public.aircraft_types enable row level security; alter table public.aircraft enable row level security; alter table public.aircraft_defects enable row level security; alter table public.maintenance_events enable row level security; alter table public.schedule_templates enable row level security; alter table public.schedule_exceptions enable row level security; alter table public.missions enable row level security; alter table public.flights enable row level security; alter table public.flight_status_events enable row level security; alter table public.qualifications enable row level security; alter table public.user_qualifications enable row level security; alter table public.crew_assignments enable row level security; alter table public.dispatch_releases enable row level security; alter table public.acars_sessions enable row level security; alter table public.flight_telemetry_points enable row level security; alter table public.flight_events enable row level security; alter table public.pireps enable row level security; alter table public.notifications enable row level security; alter table public.audit_logs enable row level security;
create policy profile_self on public.profiles for select using(id=auth.uid() or public.has_any_role(auth.uid(),array['chief_pilot','owner','system_administrator']::public.app_role[]));
create policy profile_self_update on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy public_airports on public.airports for select using(public_visibility or auth.uid() is not null);
create policy public_routes on public.routes for select using(public_visibility or auth.uid() is not null);
create policy public_flights on public.flights for select using(public_visibility or public.can_access_flight(auth.uid(),id));
create policy ops_flights on public.flights for all using(public.has_any_role(auth.uid(),array['dispatcher','chief_pilot','operations_manager','owner','system_administrator']::public.app_role[])) with check(public.has_any_role(auth.uid(),array['dispatcher','chief_pilot','operations_manager','owner','system_administrator']::public.app_role[]));
create policy own_applications on public.applications for all using(applicant_user_id=auth.uid() or public.has_any_role(auth.uid(),array['chief_pilot','owner','system_administrator']::public.app_role[])) with check(applicant_user_id=auth.uid() or public.has_any_role(auth.uid(),array['chief_pilot','owner','system_administrator']::public.app_role[]));
create policy own_pireps on public.pireps for select using(pilot_id=auth.uid() or public.has_any_role(auth.uid(),array['chief_pilot','operations_manager','owner','system_administrator']::public.app_role[]));
create policy own_pirep_insert on public.pireps for insert with check(pilot_id=auth.uid() and public.is_flight_crew(auth.uid(),flight_id));
create policy own_notifications on public.notifications for select using(user_id=auth.uid());
create policy no_client_audit_write on public.audit_logs for select using(public.has_any_role(auth.uid(),array['owner','system_administrator']::public.app_role[]));

create or replace view public.public_flight_board with (security_invoker=true) as select id,tracking_callsign,origin_airport_id,destination_airport_id,date_trunc('hour',scheduled_departure) scheduled_departure,status from public.flights where public_visibility;
grant select on public.public_flight_board to anon,authenticated;
